def test_api_failure_without_website_fallback_fails(tmp_path: Path) -> None:
    from monitor_opportunities.pipeline import _enforce_api_website_fallback

    rows = [(rid, "MATCHES") for rid, _ in _all_required()]
    rows = [(rid, "FEED_DOWN" if rid == "sam.gov" else s) for rid, s in rows]
    d = _write_receipts(
        tmp_path,
        rows,
        overrides={"sam.gov": {"channel": "api", "response_status": 503}},
    )
    with pytest.raises(ContractError, match="use the website"):
        _enforce_api_website_fallback(SKILL_DIR, d)


def test_api_failure_with_website_capture_passes(tmp_path: Path) -> None:
    import json
    from monitor_opportunities.pipeline import _enforce_api_website_fallback

    d = tmp_path / "discovery"
    d.mkdir(parents=True)
    config = _required_config()
    lines = []
    for i, (rid, _) in enumerate(_all_required()):
        required = config[rid]
        source_classes = required.get("source_classes") or ["employer_ats"]
        lines.append(json.dumps({"receipt_id": f"r{i}", "lane": required["lane"], "provider": rid, "target": rid,
            "required_source_id": rid, "channel": required["channel"], "source_class": source_classes[0],
            "result_status": "MATCHES", "observed_at": "2026-08-06T00:00:00Z",
            "request_summary": "x", "response_status": 200, "content_type": None, "response_bytes": 1,
            "content_sha256": "a" * 64, "evidence_refs": ["fixture://source"], "limitations": []}))
    # SAM API fails, but a website capture receipt exists
    lines.append(json.dumps({"receipt_id": "sam_api", "lane": "B", "provider": "sam.gov", "target": "sam",
        "required_source_id": "sam.gov", "channel": "api", "source_class": "federal_feed",
        "result_status": "FEED_DOWN", "observed_at": "2026-08-06T00:00:00Z",
        "request_summary": "x", "response_status": 404, "content_type": None, "response_bytes": 0,
        "content_sha256": None, "evidence_refs": [], "limitations": []}))
    lines.append(json.dumps({"receipt_id": "sam_web", "lane": "B", "provider": "sam.gov", "target": "sam",
        "required_source_id": "sam.gov", "channel": "browser_or_api", "source_class": "sam.gov_website",
        "fallback_for_receipt_id": "sam_api", "result_status": "MATCHES", "observed_at": "2026-08-06T00:00:00Z",
        "request_summary": "x", "response_status": 200, "content_type": None, "response_bytes": 0,
        "content_sha256": "b" * 64, "evidence_refs": ["fixture://sam"], "limitations": []}))
    (d / "source-receipts.jsonl").write_text("\n".join(lines), encoding="utf-8")
    assert _enforce_api_website_fallback(SKILL_DIR, d)["api_website_fallback_enforced"] is True


def test_federal_website_receipt_binds_evidence_hash(tmp_path: Path) -> None:
    import json

    from monitor_opportunities.required_source_receipts import federal_website_receipt

    evidence = {
        "schema_version": "monitor_opportunities.federal_capture.v1",
        "source": "sam_sgs_search_service",
        "capture_method": "httpx_read_only_sgs",
        "observed_at": "2026-08-14T22:00:00Z",
        "opportunities": [
            {
                "title": "Artificial intelligence assurance services",
                "url": "https://sam.gov/opp/hash-test/view",
                "opp_id": "hash-test",
            }
        ],
    }
    evidence_path = tmp_path / "sam-website-evidence.json"
    evidence_path.write_text(json.dumps(evidence), encoding="utf-8")

    receipt, candidates = federal_website_receipt(evidence_path)

    assert receipt["source_class"] == "sam.gov_website"
    assert receipt["content_type"] == "application/json"
    assert receipt["content_sha256"]
    assert receipt["response_bytes"] == evidence_path.stat().st_size
    assert candidates


def test_federal_website_receipt_emits_only_relevant_candidates(tmp_path: Path) -> None:
    """SAM website capture: on-mandate notices become lane-B candidates, noise drops.

    Previously the receipt discarded every captured notice (returned []), so lane B
    produced 0 candidates even on a successful capture.
    """
    import json

    from monitor_opportunities.required_source_receipts import federal_website_receipt

    ev = tmp_path / "sam-website-evidence.json"
    ev.write_text(json.dumps({
        "schema_version": "monitor_opportunities.federal_capture.v1",
        "opportunities": [
            {"title": "Artificial Intelligence Threat Detection Platform",
             "url": "https://sam.gov/workspace/contract/opp/aaaa1111/view", "opp_id": "aaaa1111"},
            {"title": "Greenhouse Ridge Vent Replacements",
             "url": "https://sam.gov/workspace/contract/opp/bbbb2222/view", "opp_id": "bbbb2222"},
        ],
    }), encoding="utf-8")

    receipt, cands = federal_website_receipt(ev)
    assert receipt["result_status"] == "MATCHES"
    assert len(cands) == 1  # only the AI notice survives the relevance gate
    c = cands[0]
    assert c["lane"] == "B" and c["organization"] == "Federal (SAM.gov)"
    assert c["candidate_id"] == "candidate:b:sam:aaaa1111"
    assert c["source_receipt_id"] == receipt["receipt_id"]
    assert c["source_receipt_id"]
    assert 0.5 <= c["fit_score"] <= 0.85


